    private InterpShimRegistry() {
    }

    /** Whether a shim exists for the given JVM internal name. */
    public static boolean canExtend(String internalName) {
        return CLASS_IDS.containsKey(internalName);
    }

    /** Whether a shim exists implementing the given interface. */
    public static boolean canImplement(String internalName) {
        return IFACE_IDS.containsKey(internalName);
    }

