    /**
     * The JVM internal name of a shim instance.
     *
     * <p>Registered by the shim itself rather than read from
     * getClass().getName(), which ParparVM derives from the mangled C
     * symbol -- where a package separator and an underscore are the
     * same character, so Interp_ui_Form comes back as Interp/ui/Form.</p>
     */
    public static String nameOf(Object peer) {
        return peer == null ? null
                : (String)PEER_NAMES.get(peer.getClass());
    }

